(** Exact generated byte equality and signed greater-than assignments.
    The word-wide lexicographic arithmetic bridge is a separate obligation. *)
From Coq Require Import ZArith List Lia.
Require Import Lang.ExtendedSV Lang.ExtendedSVBlocking Lang.ExtendedSVRootProjection
  Lang.ExtendedSVBitSlice Ex.Generated.CV32E40PExtendedAST
  Ex.External.CV32E40PAddiAdderBits Ex.External.CV32E40PAddiIDEXAccept.
Import ListNotations ExtendedSV ExtendedSVBlocking ExtendedSVRootProjection
  ExtendedSVBitSlice CV32E40PExtendedAST CV32E40PAddiAdderBits CV32E40PAddiIDEXAccept.
Local Open Scope Z_scope.
Module CV32E40PCompareByteCone.

Lemma assign_bit_value s proc root total offwidth off e :
  process_body proc = SAssign false e (LSel 1 (LVar total root) (EConst offwidth off)) ->
  norm offwidth off = off -> 0 <= off ->
  read_slice (read_signal (run_process cv32e40p_program s proc) root) off 1 =
    norm 1 (eval_expr s e).
Proof.
  intros Hbody Hoff Hnonneg.
  rewrite blocking_run_process by (rewrite Hbody; reflexivity).
  change (statement_fuel cv32e40p_program) with 512%nat. rewrite Hbody.
  cbv beta iota zeta delta [exec_stmt blocking_state apply_update resolve_update
    resolve_lvalue update_signal update_offset update_width update_value].
  cbn [eval_expr]. rewrite Hoff, Z.add_0_l, read_signal_write_same.
  rewrite read_slice_write_same by lia.
  unfold read_slice. rewrite Z.shiftr_0_r.
  change (norm 1 (norm 1 (eval_expr s e)) = norm 1 (eval_expr s e)).
  apply norm_twice.
Qed.

Definition eq_process n := match n with
  | 0%nat => process_563 | 1%nat => process_564
  | 2%nat => process_565 | _ => process_566 end.
Definition greater_process n := match n with
  | 0%nat => process_587 | 1%nat => process_588
  | 2%nat => process_589 | _ => process_590 end.
Definition assigned_expr proc := match process_body proc with
  | SAssign _ e _ => e | _ => EConst 1 0 end.

Theorem actual_byte_equal s n : (n < 4)%nat ->
  read_slice (read_signal (run_process cv32e40p_program s (eq_process n)) 1353%nat)
    (Z.of_nat n) 1 = norm 1 (eval_expr s (assigned_expr (eq_process n))).
Proof.
  intros Hn. do 4 (destruct n as [|n];
    [cbn [eq_process assigned_expr process_563 process_564 process_565 process_566 process_body];
      eapply assign_bit_value; [reflexivity|reflexivity|lia]|]). lia.
Qed.
Theorem actual_byte_greater s n : (n < 4)%nat ->
  read_slice (read_signal (run_process cv32e40p_program s (greater_process n)) 1354%nat)
    (Z.of_nat n) 1 = norm 1 (eval_expr s (assigned_expr (greater_process n))).
Proof.
  intros Hn. do 4 (destruct n as [|n];
    [cbn [greater_process assigned_expr process_587 process_588 process_589 process_590 process_body];
      eapply assign_bit_value; [reflexivity|reflexivity|lia]|]). lia.
Qed.
Print Assumptions actual_byte_equal.
Print Assumptions actual_byte_greater.
End CV32E40PCompareByteCone.
